use serde_json::{Value, Result};

pub fn solve(input: Value) -> Result<Value> {
    let jobs = input["jobs"].as_array().unwrap();
    let quantum = input["quantum"].as_u64().unwrap();

    let mut jobs = jobs.iter().enumerate().collect::<Vec<(usize, u64)>>();
    jobs.sort_unstable_by_key(|&(i, _)| i);

    let mut result = Vec::new();
    let mut remaining_quantum = quantum;

    for (i, &job) in jobs {
        if remaining_quantum >= job {
            result.push(i as u64);
            remaining_quantum -= job;
        } else {
            result.push(i as u64);
            break;
        }
    }

    Ok(Value::Array(result))
}
